const requiredNameText={'en-CA':'Player Name is required.','fr-CA':'Le nom du joueur est obligatoire.','fr-FR':'Le nom du joueur est obligatoire.','es-ES':'El nombre del jugador es obligatorio.','de-DE':'Der Spielername ist erforderlich.','it-IT':'Nome giocatore è obbligatorio.','pt-PT':'O nome do jogador é obrigatório.','nl-NL':'Spelersnaam is verplicht.','pl-PL':'Nazwa gracza jest wymagana.','ja-JP':'プレイヤー名は必須です。','zh-CN':'必须填写玩家名称。'};
function updateNameErrorText(){const error=$('#name-error');if(error)error.textContent=requiredNameText[selectedLanguage]||requiredNameText['en-CA']}
