function validateName(){const value=$('#player-name').value.trim(),input=$('#player-name'),invalid=!value;updateNameErrorText();nameError.hidden=!invalid;input.style.borderColor=invalid?'#ff7659':'#a8e3bc';input.style.boxShadow=invalid?'0 0 0 3px #fb614244':'none';if(!invalid){settings.name=value.toUpperCase();renderRoster()}return !invalid}
function currencyAmount(n){const c=currencyInfo[settings.currency],amount=n*c.rate;return settings.currency==='jpy'?Math.round(amount):Number(amount.toFixed(2))}
function format(n){const c=currencyInfo[settings.currency],amount=currencyAmount(n);return c.symbol+(settings.currency==='jpy'?amount:amount.toFixed(2))}
function formatBudget(amount){const c=currencyInfo[settings.currency];return c.symbol+(settings.currency==='jpy'?Math.round(amount):amount.toFixed(2))}
function changeScreen(id){$$('.screen').forEach(s=>s.classList.remove('active'));$('#'+id).classList.add('active')}
function selectOne(selector,current){$$(selector).forEach(b=>b.classList.toggle('selected',b===current))}
function showStep(n){step=Math.max(0,Math.min(2,n));$$('#setup .setup-panel').forEach((p,i)=>p.classList.toggle('active',i===step));$('#step-count').textContent=`${step+1} / 3`}
function applyAvatar(node){node.classList.remove('blue','violet','coral','outfit-orange','outfit-blue','outfit-green','outfit-yellow','outfit-pink','outfit-black','sex-female','sex-male');node.classList.add('outfit-'+settings.avatar,'sex-'+settings.sex)}
applyAvatar($('#creator-preview'));
function updateReady(){const c=currencyInfo[settings.currency];$('#ready-name').textContent=settings.name||'YOU';$('#ready-location').textContent=stores[settings.store].name;$('#ready-currency').textContent=`${c.name} (${c.code})`;applyAvatar($('#ready-avatar'))}
function openSetup(mode='solo'){tutorialActive=false;playMode=mode;changeScreen('setup');showStep(0);renderRoster()}
