function tutorialTasks(){return tutorialTasksByLanguage[selectedLanguage]||tutorialTasksByLanguage['en-CA']}
function renderTutorial(){if(!tutorialActive){tutorialPanel.hidden=true;return}const tasks=tutorialTasks(),task=tasks[tutorialStep]||tasks[tasks.length-1],exerciseName=({'fr-CA':'EXERCICE','fr-FR':'EXERCICE','es-ES':'EJERCICIO','de-DE':'ÜBUNG','it-IT':'ESERCIZIO','pt-PT':'EXERCÍCIO','nl-NL':'OEFENING','pl-PL':'ĆWICZENIE','ja-JP':'エクササイズ','zh-CN':'练习'})[selectedLanguage]||'EXERCISE';tutorialPanel.hidden=false;tutorialPanel.innerHTML=`<div class="tutorial-step">${exerciseName} ${Math.min(tutorialStep+1,tasks.length)} / ${tasks.length}</div><div class="tutorial-task"><b>${task[0]}:</b> ${task[1]}</div><div class="tutorial-progress"><i style="width:${(tutorialStep/tasks.length)*100}%"></i></div>`}
function advanceTutorial(){const tasks=tutorialTasks();if(!tutorialActive)return;tutorialStep++;if(tutorialStep>=tasks.length){tutorialStep=tasks.length-1;return}renderTutorial()}
function startTutorial(){playMode='solo';battleMode='ffa';tutorialActive=true;tutorialStep=0;settings.store='food';settings.currency='usd';settings.name=settings.name||'ROOKIE';launch()}
function showTutorialComplete(){changeScreen('tutorial-complete')}
function openModeSelect(){playMode='com';changeScreen('mode-select');modeScreen.classList.add('active')}
function toReady(){updateReady();renderRoster();changeScreen('ready')}
function makeItems(){groceries=stores[settings.store].items.map(([name,price,icon,color,x,y,stock=3],index)=>({id:`${settings.store}-${index}`,name,price,icon,color,x,y,stock,maxStock:stock}))}
function draw(){const area=$('#items');area.innerHTML='';groceries.forEach((g,i)=>{const soldOut=g.stock<=0,e=document.createElement('button');e.className=`item ${soldOut?'sold-out':''}`;e.disabled=soldOut;e.dataset.index=i;const scale=.64+g.y/130;e.style.cssText=`left:${g.x}%;top:${g.y}%;--color:${g.color};--item-scale:${scale};z-index:${Math.round(g.y*10)}`;e.innerHTML=`<b class="stock-count">${soldOut?'0 LEFT':g.stock+' LEFT'}</b><b class="price">${soldOut?'SOLD OUT':format(g.price)}</b><span class="box" data-icon="${g.icon}"></span><small>${g.name}</small>`;e.onclick=()=>tryTake(i);area.append(e)});updateTakePrompt()}
function update(){const basket=activeBasket(),sum=basket.reduce((a,g)=>a+g.price,0);$('#total').textContent=format(sum);$('#regtotal').textContent=format(sum);$('#pause-total').textContent=format(sum);$('#budget').textContent=formatBudget(playerBudget);$('#cart').innerHTML=basket.length?basket.map(g=>`<span class="chip">${g.icon} ${g.name}</span>`).join(''):'Your basket is empty!';$('#player em').textContent=basket.length?`🛒${basket.length}`:'🛒'}
function nearestItem(){let match=null,best=Infinity;groceries.forEach((g,i)=>{if(g.stock<=0)return;const d=Math.hypot((g.x-playerX)*.78,(g.y-playerY));if(d<best){best=d;match={g,i,d}}});return match}
function nearCheckout(){const player=$('#player').getBoundingClientRect(),checkoutZone=$('#checkout').getBoundingClientRect(),playerCenter={x:player.left+player.width/2,y:player.top+player.height/2},checkoutCenter={x:checkoutZone.left+checkoutZone.width/2,y:checkoutZone.top+checkoutZone.height/2};return Math.hypot(playerCenter.x-checkoutCenter.x,playerCenter.y-checkoutCenter.y)<150}
function updateTakePrompt(){const near=nearestItem(),hint=$('.instructions');$$('.item').forEach(e=>e.classList.remove('near'));if(nearCheckout()){hint.textContent='PRESS E TO CHECK OUT AT THE REGISTER';return}if(near&&near.d<8){const el=$(`.item[data-index="${near.i}"]`);if(el)el.classList.add('near');hint.textContent=`PRESS T TO TAKE ${near.g.name.toUpperCase()}`}else hint.textContent='W/S: forward & back • A/D: move sideways • T: take item'}
function tryTake(index){const near=nearestItem();if(index!==undefined&&(!near||near.i!==index))return;if(!near||near.d>=8||!active||paused||countdownActive)return;const g=near.g,cost=currencyAmount(g.price);if(playerBudget<cost){$('.instructions').textContent='NOT ENOUGH BUDGET FOR THIS ITEM';return}playerBudget-=cost;g.stock--;const item={...g,owner:settings.name};cart.push(item);if(isTeamMatch())teamBasket.push(item);if(tutorialActive&&tutorialStep===4)advanceTutorial();update();draw()}
function updatePlayer(walking=false){const player=$('#player'),scale=.58+playerY/110;player.style.left=playerX+'%';player.style.top=playerY+'%';player.style.bottom='auto';player.style.zIndex=Math.round(playerY*10);player.style.transform=`scale(${scale})`;player.classList.toggle('walking',walking);updateTakePrompt()}
function refreshLeaderboard(){const board=$('.board'),name=settings.name||'YOU',playerScore=cart.reduce((total,item)=>total+item.price,0);if(playMode==='com'){const rows=[{name,score:playerScore,human:true},...comPlayers].sort((a,b)=>b.score-a.score);board.innerHTML=rows.map(p=>`${p.human?'':'<span class="bot">🤖</span>'}${p.name} <b>${format(p.score)}</b>`).join('<br>')}else board.innerHTML=`${name} <b>${format(playerScore)}</b><br>CASA CART <b>${format(18.75)}</b><br>QUICK MARTY <b>${format(13.2)}</b>`}
function buildFinalStandings(finalScore){const human={name:settings.name||'YOU',score:Number(finalScore),human:true};if(playMode==='com'){comPlayers.forEach(bot=>{if(!Number.isFinite(bot.score)||bot.score<=0)bot.score=finalScore*(.25+Math.random()*.65)});if(isTeamMatch()){const [first,second]=teamNames();finalStandings=[{name:first,score:finalScore+comPlayers.filter(bot=>bot.team===first).reduce((sum,bot)=>sum+bot.score,0),human:true,team:'apple',icon:teamIconFor(first)},{name:second,score:comPlayers.filter(bot=>bot.team===second).reduce((sum,bot)=>sum+bot.score,0),human:false,team:'ice',icon:teamIconFor(second)}]}else finalStandings=[human,...comPlayers.map(bot=>({name:bot.name,score:Number(bot.score),human:false}))]}else finalStandings=[human,{name:'CASA CART',score:18.75,human:false},{name:'QUICK MARTY',score:13.2,human:false}];finalStandings.sort((a,b)=>b.score-a.score);return finalStandings}
function renderFinalLeaderboard(finalScore){const rows=isTeamMatch()?buildFinalStandings(finalScore):(roundResults||buildFinalStandings(finalScore)),board=$('.board');if(isTeamMatch()){board.className='board team-result-table';board.innerHTML=`<div class="team-result-row header"><span>${subtitleText('rank')}</span><span>${subtitleText('teamName')}</span><b>${subtitleText('amount')}</b></div>`+rows.map((team,index)=>`<div class="team-result-row ${team.team}"><span>#${index+1}</span><span><i class="team-result-icon">${team.icon}</i>${team.name}</span><b>${format(team.score)}</b></div>`).join('')}else{board.className='board';board.innerHTML=rows.map((p,index)=>`#${index+1} ${p.human?'':'<span class="bot">🤖</span>'}${p.name} <b>${format(p.score)}</b>`).join('<br>')}applyRankResult(rows);return rows[0]}
function reset(){roundResults=null;cart=[];teamBasket=[];playerBudget=650;playerX=48;playerY=73;if(playMode==='com'){const spots=[[18,62],[33,48],[50,57],[68,43],[83,60]];assignTeams();comPlayers.forEach((bot,i)=>Object.assign(bot,{score:0,budget:650,taken:0,target:null,x:spots[i][0],y:spots[i][1]}))}makeItems();const playerTeamIcon=teamIconFor(settings.team);$('#player label').innerHTML=`${playerTeamIcon?`<i class="name-team-icon">${playerTeamIcon}</i>`:''}${settings.name||'YOU'}`;applyAvatar($('#player'));update();draw();updatePlayer();refreshLeaderboard()}
function setTimer(){const m=Math.floor(seconds/60),s=seconds%60;$('#timer').textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;$('#timer').classList.toggle('warning',seconds<=60)}
function runTimer(){clearInterval(timerId);timerId=setInterval(()=>{seconds--;setTimer();if(seconds<=0){clearInterval(timerId);checkout(true)}},1000)}
function startTimer(){seconds=300;setTimer();runTimer()}
function pauseGame(){if(!active||paused||countdownActive)return;paused=true;clearInterval(timerId);clearInterval(botTimer);$('#game').classList.add('paused');pauseMenu.hidden=false;$('#quit-confirm').hidden=true}
function resumeGame(){if(!paused)return;paused=false;$('#game').classList.remove('paused');pauseMenu.hidden=true;runTimer();startBots()}
function quitToTitle(){clearInterval(timerId);clearInterval(botTimer);clearInterval(waitTimer);clearTimeout(countdownId);countdownId=null;countdownActive=false;matchCountdown.hidden=true;active=false;paused=false;tutorialActive=false;tutorialPanel.hidden=true;pauseMenu.hidden=true;$('#game').classList.remove('paused','tutorial');changeScreen('title')}
function startMatchCountdown(){clearTimeout(countdownId);clearInterval(timerId);clearInterval(botTimer);countdownActive=true;seconds=300;setTimer();heldMovementKeys.clear();if(heldMovementFrame){cancelAnimationFrame(heldMovementFrame);heldMovementFrame=null}clearTimeout(move.stop);$('#player').classList.remove('walking');matchCountdown.hidden=false;const message=$('#countdown-message'),value=$('#countdown-value'),phase=(text,number,duration,next)=>{message.textContent=text;value.textContent=number;countdownId=setTimeout(next,duration)};phase(countdownText('prepare'),'',5000,()=>phase('','3',1000,()=>phase('','2',1000,()=>phase('','1',1000,()=>{countdownActive=false;startBots();startTimer();phase('',countdownText('go'),2000,()=>{matchCountdown.hidden=true;countdownId=null})}))))}
function launch(){changeScreen('game');active=true;$('#game').classList.toggle('tutorial',tutorialActive);$('#game').classList.toggle('com-match',playMode==='com');$('#game').classList.toggle('tech-floor',settings.store==='tech');$('#game-location').textContent=stores[settings.store].name;$('#back-sign').textContent=stores[settings.store].sign;$('#shelf-left').textContent=stores[settings.store].shelves[0];$('#shelf-right').textContent=stores[settings.store].shelves[1];reset();renderComPlayers();renderTeamHud();renderTutorial();if(playMode==='com')startMatchCountdown();else{countdownActive=false;matchCountdown.hidden=true;startTimer()}}
function blockedByCheckout(x,y){const store=$('#game .store').getBoundingClientRect(),register=$('#checkout').getBoundingClientRect(),px=store.left+store.width*x/100,py=store.top+store.height*y/100;return px>register.left-22&&px<register.right+22&&py>register.top-18&&py<register.bottom-24}
function blockedByShelf(x,y){const store=$('#game .store').getBoundingClientRect(),px=store.left+store.width*x/100,py=store.top+store.height*y/100;return [...$$('.shelf'),...$$('#game.tech-floor .tech-table')].some(shelf=>{const bounds=shelf.getBoundingClientRect();return px>bounds.left-18&&px<bounds.right+18&&py>bounds.top-14&&py<bounds.bottom+20})}
function move(dx,dy){if(!active||paused||countdownActive)return;const nextX=Math.max(7,Math.min(88,playerX+dx)),nextY=Math.max(28,Math.min(76,playerY+dy));if(blockedByCheckout(nextX,nextY)||blockedByShelf(nextX,nextY))return;playerX=nextX;playerY=nextY;if(tutorialActive&&((tutorialStep===0&&dy<0)||(tutorialStep===1&&dy>0)||(tutorialStep===2&&dx<0)||(tutorialStep===3&&dx>0)))advanceTutorial();updatePlayer(true);clearTimeout(move.stop);move.stop=setTimeout(()=>$('#player').classList.remove('walking'),360)}
const heldMovementKeys=new Set();let heldMovementFrame=null;
function updateHeldMovement(){const horizontal=(heldMovementKeys.has('KeyD')||heldMovementKeys.has('ArrowRight')?1:0)-(heldMovementKeys.has('KeyA')||heldMovementKeys.has('ArrowLeft')?1:0),vertical=(heldMovementKeys.has('KeyS')||heldMovementKeys.has('ArrowDown')?1:0)-(heldMovementKeys.has('KeyW')||heldMovementKeys.has('ArrowUp')?1:0);if(!active||paused||countdownActive||(!horizontal&&!vertical)){heldMovementFrame=null;clearTimeout(move.stop);$('#player').classList.remove('walking');return}const length=Math.hypot(horizontal,vertical),speed=.34;move(horizontal/length*speed,vertical/length*speed);heldMovementFrame=requestAnimationFrame(updateHeldMovement)}
function beginHeldMovement(code){heldMovementKeys.add(code);if(!heldMovementFrame)heldMovementFrame=requestAnimationFrame(updateHeldMovement)}
function endHeldMovement(code){heldMovementKeys.delete(code);if(!heldMovementKeys.size){clearTimeout(move.stop);$('#player').classList.remove('walking')}}
function paintFinalBoard(rows){if(isTeamMatch()){renderFinalLeaderboard(cart.reduce((sum,item)=>sum+item.price,0));return}const board=$('.board');board.className='board';board.innerHTML=rows.map((player,index)=>`#${index+1} ${player.human?'':'<span class="bot">🤖</span>'}${player.name} <b>${format(player.score)}</b>`).join('<br>')}
function enforceFinalBoard(){if(!$('#results').classList.contains('active')||!cart.length)return;const rows=roundResults||buildFinalStandings(cart.reduce((sum,item)=>sum+item.price,0));const signature=rows.map(player=>`${player.name}:${player.score}`).join('|');if($('.board').dataset.roundSignature!==signature){paintFinalBoard(rows);$('.board').dataset.roundSignature=signature}}
new MutationObserver(enforceFinalBoard).observe($('#results'),{attributes:true,attributeFilter:['class']});
const rankResultTitles={'en-CA':['SUPER SHOPPER!','ALMOST THERE!','NICE TRY!','KEEP SHOPPING!'],'fr-CA':['SUPER CLIENT !','PRESQUE !','BIEN ESSAYÉ !','CONTINUEZ À MAGASINER !'],'fr-FR':['SUPER CLIENT !','PRESQUE !','BIEN ESSAYÉ !','CONTINUEZ À FAIRE VOS ACHATS !'],'es-ES':['¡SUPER COMPRADOR!','¡CASI!','¡BUEN INTENTO!','¡SIGUE COMPRANDO!'],'de-DE':['SUPER-KÄUFER!','FAST GESCHAFFT!','GUTER VERSUCH!','WEITER EINKAUFEN!'],'it-IT':['SUPER CLIENTE!','QUASI!','BEL TENTATIVO!','CONTINUA A FARE ACQUISTI!'],'pt-PT':['SUPER COMPRADOR!','QUASE!','BOA TENTATIVA!','CONTINUA A COMPRAR!'],'nl-NL':['SUPER KOPER!','BIJNA!','GOEDE POGING!','BLIJF WINKELEN!'],'pl-PL':['SUPER KUPUJĄCY!','PRAWIE!','DOBRA PRÓBA!','KUPUJ DALEJ!'],'ja-JP':['スーパー買い物客！','あと少し！','おしい！','買い物を続けよう！'],'zh-CN':['超级购物者！','就差一点！','再接再厉！','继续购物！']};
function rankTitle(index){return(rankResultTitles[selectedLanguage]||rankResultTitles['en-CA'])[index]}
function rankResultCopy(rank){if(rank===1)return{title:rankTitle(0),message:subtitleText('winner')};if(rank===2)return{title:rankTitle(1),message:subtitleText('almost')};if(rank===3)return{title:rankTitle(2),message:subtitleText('defeated')};return{title:rankTitle(3),message:subtitleText('smallest')}}
function applyRankResult(rows,outOfTime=false){const humanName=settings.name||'YOU',rank=Math.max(1,rows.findIndex(entry=>entry.human===true||entry.name===humanName)+1),copy=rankResultCopy(rank);$('#winner').textContent=outOfTime?'TIME UP!':copy.title;$('#results-message').textContent=outOfTime?'The clock ran out before the shopping was finished.':copy.message;return rank}
function showResults(sum,outOfTime=false){changeScreen('results');$('#results-quit-confirm').hidden=true;renderFinalLeaderboard(sum);const teamScore=isTeamMatch()?finalStandings.find(team=>team.human).score:sum,resultRows=isTeamMatch()?finalStandings:(roundResults||finalStandings);$('#results .card > span').textContent=isTeamMatch()?subtitleText('teamChecked'):subtitleText('checked');$('#final').textContent=format(teamScore);$('#your-score').textContent=format(teamScore);applyRankResult(resultRows,outOfTime);$('#results-kicker').textContent=menuText('results');setTimeout(()=>{paintFinalBoard(resultRows);applyRankResult(resultRows,outOfTime);$('#results-kicker').textContent=menuText('results')},50)}
function renderWaiting(){const list=$('#waiting-players');list.innerHTML=comPlayers.map(bot=>`<div class="wait-row ${bot.finished?'done':''}"><span><i class="robot">🤖</i>${bot.name}${battleMode==='team'?` · ${bot.team}`:''}</span><span class="status">${bot.finished?subtitleText('finished'):subtitleText('checking')}</span></div>`).join('')}
function waitForPlayers(sum,outOfTime){comPlayers.forEach(bot=>bot.finished=false);changeScreen('waiting');renderWaiting();let next=0;clearInterval(waitTimer);waitTimer=setInterval(()=>{const bot=comPlayers[next++];if(bot){bot.score=Math.max(bot.score,sum*(.2+Math.random()*1.2));bot.finished=true;renderWaiting()}if(next>=comPlayers.length){clearInterval(waitTimer);roundResults=[{name:settings.name||'YOU',score:Number(sum),human:true},...comPlayers.map(bot=>({name:bot.name,score:Number(bot.score),human:false}))].sort((a,b)=>b.score-a.score);setTimeout(()=>showResults(sum,outOfTime),650)}},900)}
function checkout(outOfTime=false){if(!active||paused||countdownActive)return;if(!outOfTime&&!nearCheckout())return;if(tutorialActive&&!outOfTime&&tutorialStep<5){renderTutorial();return}if(!cart.length&&!outOfTime)return;const completedTutorial=tutorialActive;active=false;tutorialActive=false;tutorialPanel.hidden=true;$('#game').classList.remove('tutorial');clearInterval(timerId);clearInterval(botTimer);if(completedTutorial){showTutorialComplete();return}const sum=cart.reduce((a,g)=>a+g.price,0);if(playMode==='com')waitForPlayers(sum,outOfTime);else showResults(sum,outOfTime)}
$('#start').onclick=startTutorial;$('#start').addEventListener('pointerup',event=>{event.preventDefault();if($('#title').classList.contains('active'))startTutorial()});titleActions.addEventListener('click',event=>{if(event.target.closest('#start')&&$('#title').classList.contains('active'))startTutorial()});comButton.onclick=()=>openModeSelect();comButton.addEventListener('pointerup',event=>{event.preventDefault();openModeSelect()});multiButton.onclick=()=>multiModal.hidden=false;multiModal.querySelector('button').onclick=()=>multiModal.hidden=true;$('#launch').onclick=launch;$('#again').onclick=()=>openSetup(playMode);$('#resume-game').onclick=resumeGame;$('#quit-game').onclick=()=>$('#quit-confirm').hidden=false;$('#quit-no').onclick=()=>$('#quit-confirm').hidden=true;$('#quit-yes').onclick=quitToTitle;$('#results-quit').onclick=()=>$('#results-quit-confirm').hidden=false;$('#results-quit-no').onclick=()=>$('#results-quit-confirm').hidden=true;$('#results-quit-yes').onclick=quitToTitle;$('#retry-tutorial').onclick=startTutorial;$('#tutorial-title').onclick=quitToTitle;
