document.addEventListener('keydown',e=>{if(e.target.matches('input, textarea'))return;if(['KeyW','KeyA','KeyS','KeyD','KeyT','KeyE','Space','ArrowLeft','ArrowRight','Escape'].includes(e.code))e.preventDefault();if(e.code==='Space'){if($('#title').classList.contains('active'))startTutorial();else if($('#mode-select').classList.contains('active')){randomizeComPlayers();openSetup('com')}else if($('#setup').classList.contains('active')){if(step===1&&!validateName())return;step===2?toReady():showStep(step+1)}else if($('#ready').classList.contains('active'))launch()}if(e.code==='Escape'){if($('#game').classList.contains('active')){if($('#quit-confirm').hidden)paused?resumeGame():pauseGame();else $('#quit-confirm').hidden=true}else if($('#ready').classList.contains('active')){changeScreen('setup');showStep(2)}else if($('#setup').classList.contains('active'))step===0?(playMode==='com'?openModeSelect():changeScreen('title')):showStep(step-1);else if($('#mode-select').classList.contains('active'))changeScreen('title')}if(['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))beginHeldMovement(e.code);if(e.code==='KeyT')tryTake();if(e.code==='KeyE')checkout()});
